<script setup>
import GettingStarted from '../GettingStarted.vue'
import OwnerAccess from './OwnerAccess.vue'
import SubscriptionAdmin from './SubscriptionAdmin.vue'
import BrandLogo from '../BrandLogo.vue'
import {ref,onMounted} from 'vue'
import Icon from '../Icon.vue'
import Wallet from '../commerce/Wallet.vue'
import OnboardingSettings from './OnboardingSettings.vue'
import {request} from './client'
const props=defineProps({session:Object})
const tab=ref('Overview'),summary=ref({}),pending=ref([]),error=ref(''),busy=ref(false),note=ref(''),reason=ref(''),workspace=ref('')
const tabs=['Overview','Subscriptions','Verification','Payouts','Signup & privacy','Admin access','Platform guide']
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function refresh(){[summary.value,pending.value]=await Promise.all([request('portal_session','overview'),request('profiles','pending')])}
async function verify(p,decision){await run(async()=>{await request('profiles','review',{profile:p.name,decision,reason:reason.value,workspace:workspace.value});await refresh();note.value='Verification decision saved.'})}
onMounted(()=>run(refresh))
</script>
<template><div class="owner-shell"><aside><a class="entry-brand" href="#"><BrandLogo/></a><span class="owner-tag">SUPER ADMIN</span><nav><button v-for="name in tabs" :class="{active:tab===name}" @click="tab=name">{{name}}</button></nav><small>Platform decisions.<br>One calm control room.</small><a href="/api/method/logout">Sign out</a></aside><main><header class="page-heading"><div><span class="eyebrow">YOUR PLATFORM, THOUGHTFULLY MANAGED</span><h1>{{tab==='Overview'?'Room to grow.':tab}}</h1><p>Private owner workspace · {{session.user}}</p></div><button class="button subtle" :disabled="busy" @click="run(refresh)"><Icon name="RefreshCw" :size="16"/>Refresh</button></header><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="note" role="status" class="form-note">{{note}}</p>
<template v-if="tab==='Overview'"><div class="owner-metrics"><article v-for="(value,key) in summary" class="panel"><span>{{key.replaceAll('_',' ')}}</span><strong>{{value}}</strong></article></div><section class="panel owner-block"><span class="eyebrow">CLEAR PRICES. CLEAR PERMISSIONS.</span><h2>One monthly subscription. Clear country pricing.</h2><p>Review verified billing countries, monthly subscriptions and received bank payments. New accounts receive one 14-day trial.</p><button class="button primary" @click="tab='Subscriptions'">Manage subscriptions <Icon name="ArrowRight" :size="16"/></button></section></template>
<OwnerAccess v-else-if="tab==='Admin access'"/>
<SubscriptionAdmin v-else-if="tab==='Subscriptions'"/>
<section v-else-if="tab==='Verification'" class="panel owner-block"><h2>Provider verification</h2><label>Institute workspace record ID (required for institutes)<input v-model="workspace" placeholder="The configured IL Institute record on this site"></label><p>Institute approval grants administration of this workspace. Each institute requires its own Frappe site.</p><label>Review reason<textarea v-model="reason" maxlength="1000" placeholder="Record the evidence reviewed and your decision"></textarea></label><article v-for="p in pending" class="owner-review"><div><strong>{{p.display_name}}</strong><p>@{{p.username}} · {{p.kind}} · {{p.country}}</p></div><button class="button primary" :disabled="busy||!reason.trim()" @click="verify(p,'Verified')">Verify & issue code</button><button class="button subtle" :disabled="busy||!reason.trim()" @click="verify(p,'Rejected')">Reject</button></article><p v-if="!pending.length">No profiles awaiting verification.</p></section>
<GettingStarted v-else-if="tab==='Platform guide'" role="Super Admin"/><OnboardingSettings v-else-if="tab==='Signup & privacy'"/><Wallet v-else-if="tab==='Payouts'" :member="{role:'PlatformAdmin',user:session.user,name:session.user}"/>
</main></div></template>
<style>.owner-shell{min-height:100vh;background:rgb(108 106 238 / 4%);color:#44364f;display:grid;grid-template-columns:230px 1fr;--student-card:#fff;--student-ink:#44364f;--student-muted:#80718d;--student-border:rgb(108 106 238 / 8%);--student-soft:rgb(108 106 238 / 6%);--student-accent:#6C6AEE}.owner-shell aside{padding:38px 25px;background:#fffcff;border-right:1px solid rgb(108 106 238 / 8%);display:flex;flex-direction:column;gap:28px}.owner-tag{font-size:10px;letter-spacing:2px;color:#957cab}.owner-shell nav{display:grid;gap:8px}.owner-shell nav button{padding:15px;text-align:left;background:none;border:0;border-radius:12px;color:#766582;cursor:pointer}.owner-shell nav button.active{background:rgb(108 106 238 / 8%);color:#745294;font-weight:600}.owner-shell aside small{margin-top:auto;line-height:1.8;color:#8c7a99}.owner-shell aside>a:last-child{font-size:12px;color:#6C6AEE}.owner-shell main{padding:50px;min-width:0;max-width:1500px}.owner-shell h1{margin:12px 0}.owner-shell .page-heading p{font-size:12px}.owner-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.owner-metrics article{padding:25px}.owner-metrics span{font-size:12px;text-transform:capitalize;color:#8b7a98}.owner-metrics strong{display:block;font-size:36px;margin-top:15px}.owner-block{padding:30px;margin-top:25px}.owner-block p{font-size:13px;line-height:1.9;margin:15px 0}.owner-fields{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:25px 0}.owner-block label{display:flex;flex-direction:column;gap:9px;font-size:12px}.owner-block :is(input,select,textarea){padding:13px;border-radius:10px;border:1px solid rgb(108 106 238 / 12%);background:rgb(108 106 238 / 4%);color:#53425f;min-width:0}.owner-calculator{padding:20px;background:rgb(108 106 238 / 6%);border-radius:16px;display:flex;gap:25px;align-items:center;margin-bottom:24px;flex-wrap:wrap}.owner-calculator strong{font-size:25px}.owner-calculator small{font-size:11px;flex-basis:100%}.owner-table{overflow:auto}.owner-table table{width:100%;font-size:12px;border-collapse:collapse}.owner-table :is(th,td){padding:15px;text-align:left;border-bottom:1px solid rgb(108 106 238 / 8%)}.owner-review{display:flex;align-items:center;gap:15px;padding:24px 0;border-bottom:1px solid rgb(108 106 238 / 8%)}.owner-review>div{flex:1}@media(max-width:800px){.owner-shell{display:block}.owner-shell aside{padding:18px}.owner-shell nav{display:flex;overflow:auto}.owner-shell aside small,.owner-tag{display:none}.owner-shell main{padding:24px}.owner-metrics{grid-template-columns:1fr 1fr}.owner-fields{grid-template-columns:1fr}.owner-review{flex-wrap:wrap}}
</style>
